public final class NonPokemonBatch115Test {
    static final UUID A=DynamicPassiveModifierTest.A,B=DynamicPassiveModifierTest.B;
    static final List<String> IDS=List.of("sm7_en_141");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(){return NonPokemonBatch2Test.DATA.trainer(IDS.getFirst()).orElseThrow();}
    static ServerMatch game(List<AbilityDefinition> abilities){return DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),NonPokemonBatch113Test.profile(),NonPokemonBatch109Test.recycle(),GeneratedRuleBatch8Test.hit(100,false),abilities,0,profile());}
    static ServerMatch game(){return game(List.of());}
    static boolean attached(ServerMatch m,UUID p,UUID host,CardInstance c){return EventTargetBindingTest.field(m).pokemonView(p,host).attachedEnergyIds().contains(c.instanceId());}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    static CardInstance deckEnergy(ServerMatch m,UUID p){var c=hand(m,p,"energy");PairedTrainerPlayTest.zone(m,p,"hand").remove(c);PairedTrainerPlayTest.zone(m,p,"deck").add(c);return c;}
    static void selectOld(ServerMatch m,UUID p,CardInstance old){m.playTrainer(p,hand(m,p,"item").instanceId(),null);var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(old.instanceId()));}
    static ServerMatch aiGame(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.attack=GeneratedRuleBatch8Test.hit(300,false);c.defenderAttack=c.attack;var m=GeneratedRuleBatch28Test.fixture(c);for(UUID p:List.of(GeneratedRuleBatch8Test.A,GeneratedRuleBatch8Test.B)){m.attachEnergyByEffect(m.currentPlayer(),p,EffectSourceZone.HAND,hand(m,p,"energy").instanceId(),p,active(m,p));deckEnergy(m,p);}return m;}
    public static void main(String[] args){exchange();failureToFind();authority();eventsAndProtection();ai();schema();System.out.println("NonPokemonBatch115Test passed: both owners/positions, Basic/Special/foreign physical Energy, delayed exchange, own-deck basic-only private search and failure-to-find, empty deck/no attachments, no discard replacement, exact conserved host/card identities, stale/foreign selections, Deck attachment reaction and no hand counters, protection and four AI difficulties");}
    static void exchange(){for(UUID p:List.of(A,B))for(boolean onBench:List.of(false,true))for(boolean special:List.of(false,true))for(boolean foreign:List.of(false,true)){
        var m=game();if(p.equals(B))m.endTurn(A);UUID host=onBench?bench(m,p):active(m,p),source=foreign?other(p):p;var old=hand(m,source,special?"special":"energy");m.attachEnergyByEffect(p,source,EffectSourceZone.HAND,old.instanceId(),p,host);var replacement=deckEnergy(m,p);var unrelated=hand(m,other(p),"energy");m.attachEnergyByEffect(p,other(p),EffectSourceZone.HAND,unrelated.instanceId(),other(p),active(m,other(p)));int ownCount=m.privateView(p).hand().size(),sourceCount=m.privateView(source).deck().size();
        m.playTrainer(p,hand(m,p,"item").instanceId(),null);var first=m.effectCardPrompt(p);check(first.candidates().contains(old)&&!first.candidates().contains(unrelated),"Brush included opponent attachment");m.submitEffectCards(p,first.resolutionId(),first.step(),List.of(old.instanceId()));var q=m.effectCardPrompt(p);check(q.step()!=first.step()&&q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicEnergy()),"Brush failed private basic-only second step");check(attached(m,p,host,old)&&m.privateView(p).deck().contains(replacement),"Brush detached old Energy before replacement was chosen");check(m.clientView(other(p)).effectSelection()==null,"Brush leaked private deck choices");m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(replacement.instanceId()));settle(m);
        check(!attached(m,p,host,old)&&attached(m,p,host,replacement)&&m.privateView(source).deck().contains(old)&&!m.privateView(source).hand().contains(old)&&!m.privateView(source).discard().contains(old),"Brush wrong host/physical owner/destination or Recycle Energy replacement");check(m.privateView(p).hand().size()==ownCount-1&&!m.energyAttached(p),"Brush used manual quota or put replacement in hand");check(m.privateView(source).deck().size()==sourceCount+(foreign?1:0),"Brush violated deck card conservation");
    }}
    static void failureToFind(){for(boolean noBasic:List.of(false,true)){
        var m=game();var old=hand(m,A,"special");UUID host=active(m,A);m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,old.instanceId(),A,host);deckEnergy(m,A);if(noBasic){var deck=PairedTrainerPlayTest.zone(m,A,"deck");var removed=deck.stream().filter(c->m.cardDefinition(c.definitionId()).basicEnergy()).toList();deck.removeAll(removed);PairedTrainerPlayTest.zone(m,A,"discard").addAll(removed);}int size=m.privateView(A).deck().size();selectOld(m,A,old);if(!noBasic){var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),List.of());}settle(m);check(attached(m,A,host,old)&&m.privateView(A).deck().size()==size&&!m.hasPendingEffectChoice(),"Failed Brush search moved old Energy or stalled");
    }for(boolean attach:List.of(false,true)){var m=game();if(attach){m.attachEnergy(A,hand(m,A,"energy").instanceId(),active(m,A));var deck=PairedTrainerPlayTest.zone(m,A,"deck");PairedTrainerPlayTest.zone(m,A,"discard").addAll(deck);deck.clear();}check(!m.canPlayTrainer(A,hand(m,A,"item").instanceId(),null),"Brush accepted missing attachments or empty deck");}}
    static void authority(){var m=game();var old=hand(m,A,"special");UUID host=active(m,A);m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,old.instanceId(),A,host);var replacement=deckEnergy(m,A);selectOld(m,A,old);var q=m.effectCardPrompt(A);var before=m.clientView(A);var rng=m.randomTranscript();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(B,q.resolutionId(),q.step(),List.of(replacement.instanceId())));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step()-1,List.of(old.instanceId())));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(hand(m,A,"energy").instanceId())));GeneratedRuleBatch8Test.reject(()->m.effectCardPrompt(B));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Invalid exchange altered state/RNG");m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(replacement.instanceId()));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(replacement.instanceId())));}
    static void eventsAndProtection(){var ability=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"deck-energy\",\"nameZh\":\"牌库附能监听\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_ENERGY_ATTACHED\",\"target\":\"SELF\",\"source\":\"DECK\",\"cause\":\"EFFECT\",\"optional\":false,\"usage\":\"NONE\"},\"effects\":[{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1}]}").getAsJsonObject(),EffectRegistry.standard());
        var m=game(List.of(ability));UUID host=active(m,A);var old=hand(m,A,"special");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,old.instanceId(),A,host);var replacement=deckEnergy(m,A);m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);EventTargetBindingTest.field(m).preventHandEnergy(B,A,host);int before=m.privateView(A).hand().size();selectOld(m,A,old);var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(replacement.instanceId()));settle(m);check(m.privateView(A).hand().size()==before&&m.activePokemonView(A).damage()==0&&attached(m,A,host,replacement),"Brush missed Deck event, triggered Frozen City, or obeyed hand-only lock");
        var guarded=game();UUID target=active(guarded,A);var keep=hand(guarded,A,"special");guarded.attachEnergyByEffect(A,A,EffectSourceZone.HAND,keep.instanceId(),A,target);var next=deckEnergy(guarded,A);EventTargetBindingTest.field(guarded).addProtection(A,A,target,new ProtectionEffect(new EffectProtection(EffectProtection.Source.TRAINER,EffectProtection.Relation.ANY,EffectProtection.Scope.EFFECTS_ONLY),ContinuousEffect.Expiry.LEAVES_PLAY));selectOld(guarded,A,keep);var choice=guarded.effectCardPrompt(A);guarded.submitEffectCards(A,choice.resolutionId(),choice.step(),List.of(next.instanceId()));settle(guarded);check(attached(guarded,A,target,keep)&&guarded.privateView(A).deck().contains(next),"Protected host only completed half an exchange");
    }
    static void ai(){for(var level:AiDifficulty.values()){var m=aiGame(IDS.getFirst());UUID a=GeneratedRuleBatch8Test.A,b=GeneratedRuleBatch8Test.B;m.playTrainer(a,hand(m,a,"trainer").instanceId(),null);var session=MatchSession.multiplayer(m,a,b);AiCardOperationTest.settle(session,level);AiCardOperationTest.finish(session,level);check(m.phase()==MatchPhase.FINISHED,"Brush AI stalled: "+level);}}
    static void schema(){var valid=new EffectDefinition(EnergyDeckSwap.SELECT,EffectTarget.ALL_OWN_POKEMON,Map.of(),List.of(),List.of());GeneratedRuleBatch8Test.reject(()->EnergyDeckSwap.validate(new EffectDefinition(valid.type(),EffectTarget.ALL_OPPONENT_POKEMON,Map.of(),List.of(),List.of())));GeneratedRuleBatch8Test.reject(()->EnergyDeckSwap.validate(new EffectDefinition(valid.type(),valid.target(),Map.of("minimum","0"),List.of(),List.of())));}
}
